from pwn import remote

# Server details
HOST = 'crypto.chal.csaw.io'
PORT = 5000
MSG_PATH = '/home/ctfplayer/ctf_files/messages.txt'

def main():
    with remote(HOST, PORT) as conn:
        response = b''
        # enter and record all prompts
        while True:
            try:
                data = conn.recv(timeout=2)
            except EOFError:
                break
            if not data:
                break
            response += data
            if b'password' in data.lower() or b'>' in data or b':' in data or b'close' in data.lower():
                break       # Prompt shown, ready for messages
        # Open the messages file
        with open(MSG_PATH, 'r') as f:
            lines = [l.rstrip('\n') for l in f]
        for line in lines:
            conn.sendline(line.encode())
            # receive server prompt
            try:
                r = conn.recv(timeout=2)
                if r:
                    response += r
            except EOFError:
                break
        # send 'Close'
        conn.sendline(b'Close')
        # Final output (flag?)
        try:
            while True:
                r = conn.recv(timeout=2)
                if not r:
                    break
                response += r
        except EOFError:
            pass
        print(response.decode(errors='ignore'))
if __name__ == '__main__':
    main()
